import test from 'node:test';import assert from 'node:assert/strict';import {correctProductData} from './product-title-corrections.mjs';
test('triagem76 preserva identidade operação e idempotência sem inventar medidas',()=>{for(const [id,titulo] of [['fflXJkY0fRQJg8t2QZqn',"Kit Ventilador Portatil 8'' + Luz Led 4'' 2 Baterias Recarregável Lanterna Refletor Lampada Luz Led"],['FlQInLlTCwVdemK0g3rZ','Kit 5 Potes De Vidro Marmita C/ Tampa Hermético 640ml'],['fMwDJ0aYUKjwcpHFiRus','Kit 50 Cabide Adulto Preto Reforçado Organizador Combate']]){const p={id,titulo,preco:'preservar',linkAfiliado:'https://meli.la/preservar'},x=correctProductData(p);assert.equal(x.preco,p.preco);assert.equal(x.linkAfiliado,p.linkAfiliado);assert.deepEqual(correctProductData(x),x);assert.equal(correctProductData({...p,titulo:'Outro produto',comentario:'manter'}).comentario,'manter');assert.doesNotMatch(x.pros,/garant|maior durabilidade|totalmente adequados|sem interrupção/i);assert.doesNotMatch(x.comentario,/\b\d+\s*°C|suporta \d+ kg/i);}});
